-- Local prototype only.  Users and painting favourites are deliberately kept
-- beside the versioned catalog so the R24 request path never has to write a
-- cross-database reference.  This migration does not alter V001.

CREATE TABLE catalog_users (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username VARCHAR(255) NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    full_name VARCHAR(255) NOT NULL,
    email VARCHAR(255) NOT NULL,
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    account_non_expired BOOLEAN NOT NULL DEFAULT TRUE,
    account_non_locked BOOLEAN NOT NULL DEFAULT TRUE,
    credentials_non_expired BOOLEAN NOT NULL DEFAULT TRUE,
    role VARCHAR(255) NOT NULL DEFAULT 'ROLE_USER',
    created_at TIMESTAMP NOT NULL,
    updated_at TIMESTAMP NOT NULL,
    CONSTRAINT uq_catalog_users_username UNIQUE (username),
    CONSTRAINT uq_catalog_users_email UNIQUE (email)
);

-- Same lookup predicates as the R24 authentication and profile paths.  The
-- unique constraints above are the concurrency authority for registration.
CREATE INDEX idx_catalog_users_username ON catalog_users(username);

CREATE TABLE catalog_painting_favorites (
    public_id UUID PRIMARY KEY,
    user_id BIGINT NOT NULL REFERENCES catalog_users(id) ON DELETE RESTRICT,
    painting_id UUID NOT NULL REFERENCES catalog_paintings(public_id) ON DELETE RESTRICT,
    created_at TIMESTAMP NOT NULL,
    CONSTRAINT uq_catalog_painting_favorites_user_painting UNIQUE (user_id, painting_id)
);

CREATE INDEX idx_catalog_painting_favorites_user_created
    ON catalog_painting_favorites(user_id, created_at DESC, public_id);
CREATE INDEX idx_catalog_painting_favorites_painting_user
    ON catalog_painting_favorites(painting_id, user_id);

-- Legacy-account import state is a migration ledger, not an ongoing sync.
-- An identical completed source becomes a no-op, preserving subsequent
-- PostgreSQL password changes and favourite removals.
CREATE TABLE catalog_legacy_account_imports (
    source_id TEXT PRIMARY KEY,
    source_sha256 CHAR(64) NOT NULL CHECK (source_sha256 ~ '^[0-9a-f]{64}$'),
    source_schema TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status = 'SUCCEEDED'),
    imported_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    imported_users INTEGER NOT NULL CHECK (imported_users >= 0),
    imported_favorites INTEGER NOT NULL CHECK (imported_favorites >= 0)
);

CREATE TABLE catalog_legacy_account_import_attempts (
    attempt_id UUID PRIMARY KEY,
    source_id TEXT NOT NULL,
    source_sha256 CHAR(64) NOT NULL CHECK (source_sha256 ~ '^[0-9a-f]{64}$'),
    outcome TEXT NOT NULL CHECK (outcome IN ('STARTED', 'SUCCEEDED', 'NOOP_REIMPORT', 'FAILED', 'CONFLICT')),
    failure_code TEXT,
    failure_message TEXT,
    started_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    finished_at TIMESTAMPTZ
);

CREATE INDEX idx_catalog_legacy_account_import_attempts_source
    ON catalog_legacy_account_import_attempts(source_id, started_at DESC);
